<dialog id="task-modal" class="tl-dialog" aria-labelledby="task-modal-title"><div class="tl-dialog-shell"><header class="tl-dialog-header"><h2 id="task-modal-title"></h2><button id="close-task-modal" class="tl-icon-button" type="button" aria-label="Close task details">×</button></header><div class="tl-dialog-body"><section id="tl-view-panel"><div id="tl-view-chips" class="tl-view-chips"></div><p id="task-modal-description" class="tl-task-description"></p><dl id="tl-task-facts" class="tl-facts"></dl></section><form id="task-edit-form" hidden novalidate><p id="task-edit-error" class="error" role="alert" hidden></p><label for="edit-task-title">Title</label><input id="edit-task-title" maxlength="255" required><label for="edit-task-description">Description</label><textarea id="edit-task-description" maxlength="1000" rows="3"></textarea><p id="tl-edit-description-count" class="field-count">0/1000</p><div class="tl-edit-pair"><div><label for="edit-task-priority">Priority</label><select id="edit-task-priority"><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></div><div><label for="edit-task-due-date">Due date</label><input id="edit-task-due-date" type="date"></div></div></form></div><footer class="tl-dialog-footer"><div id="tl-view-actions"><button id="tl-close-view" class="secondary" type="button">Close</button><button id="edit-task-button" class="primary" type="button">Edit task</button></div><div id="tl-edit-actions" hidden><button id="cancel-task-edit" class="secondary" type="button">Cancel</button><button id="save-task-edit" class="primary" type="submit" form="task-edit-form">Save changes</button></div></footer></div></dialog>
